// Plan:
// 1. Define a recursive function to check the nesting of brackets.
// 2. Iterate through the input string, ignoring non-bracket characters.
// 3. Use a stack to keep track of the opening brackets.
// 4. For each closing bracket, check if it matches the last opening bracket on the stack.
// 5. Return true if all brackets are properly nested, false otherwise.

use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input_str = input.as_str().unwrap();
    let mut stack = Vec::new();

    for c in input_str.chars() {
        match c {
            '{' | '[' | '(' => stack.push(c),
            '}' | ']' | ')' => {
                if stack.pop() != Some(match c {
                    '}' => '{',
                    ']' => '[',
                    ')' => '(',
                    _ => unreachable!(),
                }) {
                    return Value::Bool(false);
                }
            }
            _ => {}
        }
    }

    Value::Bool(stack.is_empty())
}
